-- SQL Schema generated by MODT

CREATE TABLE CatalogCategory (
    id INT PRIMARY KEY AUTO_INCREMENT,
    code VARCHAR(40) UNIQUE NOT NULL,
    title VARCHAR(120) NOT NULL,
    active BOOLEAN DEFAULT TRUE
);

CREATE TABLE Product (
    id INT PRIMARY KEY AUTO_INCREMENT,
    sku VARCHAR(40) UNIQUE NOT NULL,
    name VARCHAR(150) NOT NULL,
    description TEXT,
    basePrice DECIMAL(12,2) NOT NULL,
    taxCode VARCHAR(20),
    active BOOLEAN DEFAULT TRUE,
    classifies INT,
    contains INT,
    FOREIGN KEY (classifies) REFERENCES CatalogCategory(id),
    FOREIGN KEY (contains) REFERENCES ShoppingCart(id)
);

CREATE TABLE InventoryItem (
    id INT PRIMARY KEY AUTO_INCREMENT,
    quantityOnHand INT DEFAULT 0,
    reservedQty INT DEFAULT 0,
    reorderPoint INT DEFAULT 10
);

CREATE TABLE UserAccount (
    id BIGINT PRIMARY KEY,
    email VARCHAR(180) UNIQUE NOT NULL,
    passwordHash VARCHAR(255) NOT NULL,
    accountStatus VARCHAR(255),
    createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE CustomerProfile (
    id INT PRIMARY KEY AUTO_INCREMENT,
    parent INT,
    fullName VARCHAR(140) NOT NULL,
    loyaltyPoints INT DEFAULT 0,
    defaultLanguage VARCHAR(10),
    FOREIGN KEY (parent) REFERENCES UserAccount(id)
);

CREATE TABLE OperationsAdmin (
    id INT PRIMARY KEY AUTO_INCREMENT,
    parent INT,
    teamName VARCHAR(80),
    FOREIGN KEY (parent) REFERENCES UserAccount(id)
);

CREATE TABLE ShoppingCart (
    id INT PRIMARY KEY AUTO_INCREMENT,
    cartToken VARCHAR(80) UNIQUE NOT NULL,
    status VARCHAR(255),
    openedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    owns INT,
    FOREIGN KEY (owns) REFERENCES CustomerProfile(id)
);

CREATE TABLE Order (
    id INT PRIMARY KEY AUTO_INCREMENT,
    orderNumber VARCHAR(50) UNIQUE NOT NULL,
    status VARCHAR(255),
    submittedAt TIMESTAMP NULL,
    paidAt TIMESTAMP NULL,
    totalAmount DECIMAL(12,2) NOT NULL,
    places INT,
    FOREIGN KEY (places) REFERENCES CustomerProfile(id)
);

CREATE TABLE OrderLine (
    id INT PRIMARY KEY AUTO_INCREMENT,
    quantity INT NOT NULL,
    unitPrice DECIMAL(12,2) NOT NULL,
    discountAmount DECIMAL(12,2) DEFAULT 0,
    contains INT,
    for_product INT,
    FOREIGN KEY (contains) REFERENCES Order(id),
    FOREIGN KEY (for_product) REFERENCES Product(id)
);

CREATE TABLE PaymentAuthorization (
    id INT PRIMARY KEY AUTO_INCREMENT,
    providerReference VARCHAR(90),
    paymentState VARCHAR(255),
    authorizedAmount DECIMAL(12,2) NOT NULL,
    payments INT,
    FOREIGN KEY (payments) REFERENCES Order(id)
);

CREATE TABLE Shipment (
    id INT PRIMARY KEY AUTO_INCREMENT,
    trackingNumber VARCHAR(60),
    fulfillmentState VARCHAR(255),
    carrier VARCHAR(40),
    fulfills INT,
    FOREIGN KEY (fulfills) REFERENCES Order(id)
);

